# Policy example: custom policy to skip over malformed json in structured events
class SkipMalformedStructured(BaseErrorPolicy):
    async def on_error(self, event_meta, exc):
        if isinstance(exc, JSONDecodeError):
            return PolicyDecision.skip()
        return PolicyDecision.fail()
